const FONT_AWESOME_STYLES = ["solid", "brands", "regular"];

function replaceFontAwesomeIcons(root = document) {
  const selector = FONT_AWESOME_STYLES.map((style) => `i.fa-${style}`).join(",");
  root.querySelectorAll(selector).forEach((icon) => {
    const styleClass = FONT_AWESOME_STYLES.find((style) => icon.classList.contains(`fa-${style}`));
    const iconClass = [...icon.classList].find(
      (token) => token.startsWith("fa-") && token !== "fa" && token !== `fa-${styleClass}`
    );
    const iconData = styleClass && iconClass ? FONT_AWESOME_INLINE_ICONS[styleClass]?.[iconClass] : null;

    if (!iconData) {
      return;
    }

    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("viewBox", iconData.viewBox);
    svg.setAttribute("aria-hidden", icon.getAttribute("aria-hidden") || "true");
    svg.setAttribute("focusable", "false");
    svg.setAttribute("width", "1em");
    svg.setAttribute("height", "1em");
    svg.setAttribute("fill", "currentColor");
    svg.classList.add("fa-inline-icon");
    [...icon.classList].forEach((token) => svg.classList.add(token));
    svg.innerHTML = iconData.body;
    icon.replaceWith(svg);
  });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => replaceFontAwesomeIcons());
} else {
  replaceFontAwesomeIcons();
}
